function validate([board]) {
  if (!Array.isArray(board) || board.length < 3 || board.length > 50) return 'board needs 3 to 50 rows.';
  const n = board[0].length;
  if (n < 3 || n > 50) return 'board needs 3 to 50 columns.';
  if (board.some(row => !Array.isArray(row) || row.length !== n)) return 'Every row must have the same length.';
  if (board.some(row => row.some(v => !Number.isInteger(v) || v < 1 || v > 2000))) return 'Each cell starts with a candy type from 1 to 2000.';
  return null;
}

