function candyCrush(board) {
  // Each round: mark a cell when the run through it (left-right or up-down) is 3 or longer, then rebuild every column.
  let grid = board.map(row => row.slice());
  const m = grid.length, n = grid[0].length;
  for (;;) {
    const crush = grid.map(row => row.map(() => false));
    let any = false;
    for (let i = 0; i < m; i++) for (let j = 0; j < n; j++) {
      const v = grid[i][j];
      if (v === 0) continue;
      let a = j, b = j;
      while (a > 0 && grid[i][a - 1] === v) a--;
      while (b < n - 1 && grid[i][b + 1] === v) b++;
      let p = i, q = i;
      while (p > 0 && grid[p - 1][j] === v) p--;
      while (q < m - 1 && grid[q + 1][j] === v) q++;
      if (b - a >= 2 || q - p >= 2) { crush[i][j] = true; any = true; }
    }
    if (!any) return grid;
    const next = grid.map(row => row.map(() => 0));
    for (let j = 0; j < n; j++) {
      const kept = [];
      for (let i = 0; i < m; i++) if (!crush[i][j] && grid[i][j] !== 0) kept.push(grid[i][j]);
      for (let k = 0; k < kept.length; k++) next[m - kept.length + k][j] = kept[k];
    }
    grid = next;
  }
}

