function generate(rand, size) {
  const large = size === 'large';
  const m = large ? 40 + Math.floor(rand() * 11) : 3 + Math.floor(rand() * 4);
  const n = large ? 40 + Math.floor(rand() * 11) : 3 + Math.floor(rand() * 4);
  // Few candy types make lines and chain reactions likely; sometimes mix in rare large types.
  const kinds = 2 + Math.floor(rand() * (large ? 4 : 3));
  const rare = rand() < 0.3;
  const board = Array.from({ length: m }, () => Array.from({ length: n }, () => {
    if (rare && rand() < 0.25) return 1 + Math.floor(rand() * 2000);
    return 1 + Math.floor(rand() * kinds);
  }));
  return [board];
}
